export type SecondFactorAnswerPasskey = { [key: string]: unknown } | null;

/**
 * The account's own second factor, presented with a self-issued grant.
 *
 * Asked for once any ``data.bypass`` holder has one. Any of the three
 * answers is accepted: a code from the authenticator, one of the recovery
 * codes, or an assertion from one of the account's passkeys — begun at
 * ``POST /access-grants/break-glass/passkey`` so the challenge it answers
 * belongs to this request.
 */
export interface SecondFactorAnswer {
  code?: string | null;
  recovery_code?: string | null;
  passkey?: SecondFactorAnswerPasskey;
}

/**
 * The second leg of a sign-in: the challenge, and the thing it asked for.
 */
export interface SecondFactorChallengeAnswer {
  /**
   * @minLength 1
   * @maxLength 512
   */
  challenge: string;
  code?: string | null;
  recovery_code?: string | null;
}

export interface SecondFactorConfirm {
  /**
   * @minLength 1
   * @maxLength 16
   */
  code: string;
}

/**
 * Removing the factor asks for the password and for the factor itself —
 * either a live code or one of the recovery codes.
 */
export interface SecondFactorDisable {
  current_password?: string | null;
  code?: string | null;
  recovery_code?: string | null;
}

/**
 * Beginning an enrolment. The password is re-checked here, as it is for a
 * password change; an account with no usable password sends nothing.
 */
export interface SecondFactorEnrolStart {
  current_password?: string | null;
}

/**
 * The seed, once. There is no path that reads it back.
 */
export interface SecondFactorEnrolment {
  secret: string;
  otpauth_uri: string;
}

/**
 * Who to ask for a second factor from now on.
 *
 * Nobody is signed out by the change. An account the level covers is asked
 * at its next request and answers it where it stands; one that cannot
 * present a factor — the app on a phone, a personal API key — works again
 * once its owner holds one.
 */
export interface SecondFactorRequirementUpdate {
  level: SecondFactorRequirement;
}

/**
 * What the account holds, for the settings surface.
 */
export interface SecondFactorStatus {
  enrolled?: boolean;
  confirmed_at?: string | null;
  last_used_at?: string | null;
  recovery_codes_remaining?: number;
  password_required?: boolean;
  offered?: boolean;
  passwordless?: boolean;
}

/**
 * The factor, presented against a session that is already signed in.
 *
 * No challenge: the session the request is authenticated by is what names
 * the account, so there is nothing for the client to carry between two legs
 * of a sign-in that is not happening.
 */
export interface SecondFactorStepUpAnswer {
  code?: string | null;
  recovery_code?: string | null;
}

/**
 * The absolute limit on staying signed in, in hours.
 *
 * ``None`` asks for no limit. It has to be longer than the idle window to
 * mean anything: set shorter, it is the only thing ending a session and the
 * idle window stops mattering — which is a fair thing to ask for, and the
 * reason the field is free rather than a list of blessed figures.
 */
export interface SessionLifetimeUpdate {
  session_max_hours?: number | null;
  session_idle_minutes?: number | null;
}

/**
 * One browser session, as the account's own "where you're signed in" list
 * shows it.
 *
 * Beside it in that list sit the account's native devices, which are
 * :class:`DeviceTokenInfo` and a different credential — this is the rotating
 * kind a browser holds. ``started_at`` is the sign-in, not the last renewal,
 * so a browser left open for a month reads as a month old.
 *
 * ``label`` is derived from the user agent (``core.user_agents``), because
 * only a native sign-in is handed a name to go by. ``is_current`` marks the
 * session doing the asking, which the list shows rather than offers to end.
 */
export interface SignedInSessionInfo {
  id: string;
  label: string | null;
  kind: ClientKind;
  ip: string | null;
  started_at: string;
  last_used_at: string | null;
  is_current: boolean;
}

